-- =====================================================================================
-- Brand OS: starter data
-- Run AFTER 01_schema.sql. Safe to re-run: rows that already exist are skipped (INSERT IGNORE).
--
-- What it adds:
--   * 5 departments (Project Management, Creative, Shoot, Digital, Tech)
--   * 2 intake forms (E-commerce brand, Lead generation) with all their questions
--   * 2 project types (E-commerce brand: 9 stages, Lead generation: 8 stages) with their tasks
--   * 10 asset formats (Content Calendar, Shoot Requirements, ...) with their fields
--   * 1 admin login
-- It adds no clients and no other people.
--
-- BEFORE RUNNING: set the admin name and email below.
-- The first password is  ChangeMe-2026!   Sign in, then change it in Settings -> People.
-- =====================================================================================

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS = 0;

SET @admin_name  = 'Admin';
SET @admin_email = 'admin@yourcompany.com';

